#include "WorldAiEffectBatch.h"
#include "json.hpp"
#include <stdexcept>
#include <unordered_set>
namespace Silver::WorldEditor
{
namespace{using Json=nlohmann::json;constexpr std::size_t MaxBytes=2*1024*1024,MaxCommands=256;
WorldPointLight L(const Json&j){WorldPointLight x;x.Id=j.value("id",NoEffect);x.Position=j.at("position").get<std::array<float,3>>();x.Color=j.at("color").get<std::array<float,3>>();x.Intensity=j.value("intensity",1.f);x.Radius=j.value("radius",3);return x;}
WorldRuntimeEffect E(const Json&j){WorldRuntimeEffect x;x.Id=j.value("id",NoEffect);x.Preset=j.value("preset","");x.Kind=j.value("kind",0);x.Type=j.value("type",0);x.SubType=j.value("subType",0);x.Position=j.at("position").get<std::array<float,3>>();x.Scale=j.value("scale",1.f);x.Enabled=j.value("enabled",true);return x;}}
WorldAiEffectBatch WorldAiEffectBatch::Decode(std::span<const std::uint8_t>b){if(b.empty()||b.size()>MaxBytes)throw std::invalid_argument("AI EffectBatch fuera de limites.");Json j;try{j=Json::parse(std::string(reinterpret_cast<const char*>(b.data()),b.size()));}catch(const Json::exception&){throw std::invalid_argument("AI EffectBatch JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("AI EffectBatch schema incompatible.");WorldAiEffectBatch x;x.RequestId=j.value("requestId","");x.MapId=j.value("mapId",-1);x.WorldNumber=j.value("worldNumber",-1);x.Safety=j.value("safety","");if(x.RequestId.empty()||x.MapId<0||x.WorldNumber<0||x.Safety!="CANDIDATE_ONLY; NO_AUTO_APPLY")throw std::invalid_argument("AI EffectBatch inseguro/incompleto.");std::unordered_set<EffectId>ids;for(const auto&v:j.value("lights",Json::array())){if(x.Lights.size()>=MaxCommands)throw std::length_error("Demasiados light commands.");WorldAiLightCommand c;c.Id=v.value("id",NoEffect);c.Expected=L(v.at("expected"));c.Desired=L(v.at("desired"));if(c.Id==NoEffect||c.Expected.Id!=c.Id||c.Desired.Id!=c.Id||!ids.insert(c.Id).second)throw std::invalid_argument("AI Light ID invalido.");x.Lights.push_back(std::move(c));}for(const auto&v:j.value("runtimeEffects",Json::array())){if(x.RuntimeEffects.size()>=MaxCommands)throw std::length_error("Demasiados runtime effect commands.");WorldAiRuntimeEffectCommand c;c.Id=v.value("id",NoEffect);c.Expected=E(v.at("expected"));c.Desired=E(v.at("desired"));if(c.Id==NoEffect||c.Expected.Id!=c.Id||c.Desired.Id!=c.Id||!ids.insert(c.Id).second||c.Expected.Preset!=c.Desired.Preset||c.Expected.Kind!=c.Desired.Kind||c.Expected.Type!=c.Desired.Type||c.Expected.SubType!=c.Desired.SubType)throw std::invalid_argument("AI RuntimeEffect intenta cambiar identidad/preset.");x.RuntimeEffects.push_back(std::move(c));}return x;}
bool WorldAiEffectBatch::Validate(const WorldEffectDocument&d,std::string&e)const{for(const auto&c:Lights){const auto*p=d.Find(c.Id);if(!p||!(*p==c.Expected)){e="AI Light Expected no coincide.";return false;}}for(const auto&c:RuntimeEffects){const auto*p=d.FindRuntimeEffect(c.Id);if(!p||!(*p==c.Expected)){e="AI RuntimeEffect Expected no coincide.";return false;}}e.clear();return true;}
bool WorldAiEffectBatch::Apply(WorldEffectDocument&d,std::string&e)const{if(!Validate(d,e))return false;bool changed=false;for(const auto&c:Lights)changed=d.UpdatePointLight(c.Id,c.Desired)||changed;for(const auto&c:RuntimeEffects)changed=d.UpdateRuntimeEffect(c.Id,c.Desired)||changed;if(!changed){e="AI EffectBatch no produjo cambios.";return false;}e.clear();return true;}
}
